// Store preset config from React app (use global so it persists)
var config = msg.payload;
if (typeof config === 'string') {
    try { config = JSON.parse(config); } catch (e) { config = null; }
}
if (!config || typeof config !== 'object') {
    node.warn('Activate: invalid payload');
    msg.payload = { ok: false, error: 'Invalid config' };
    return msg;
}
global.set('activeConfig', config);
global.set('finnhubToken', config.finnhubToken || global.get('finnhubToken'));
var ticker = (config.rule_front && config.rule_front.data_source) || (config.rule_back && config.rule_back.data_source) || 'none';
node.warn('Config stored, ticker: ' + ticker);
msg.payload = { ok: true, message: 'Config activated', ticker: ticker };
return msg;

// Test pattern from React - pass through to MQTT and respond
var body = msg.payload;
var pattern = (body.pattern || 'pulse_all').toString();
if (pattern !== 'rising' && pattern !== 'falling') pattern = 'pulse_all';
var intensity = body.intensity || 50;
if (intensity < 40) intensity = 40;
var mqttPayload = {
    intensity: intensity,
    direction: body.direction || 'up',
    pattern: pattern,
    price: body.price || 0,
    change: body.change || 0
};
var mqttMsg = { ...msg, payload: mqttPayload };
var responseMsg = { ...msg, payload: { ok: true, message: 'Test pattern sent' } };
return [mqttMsg, responseMsg];

// Get ticker from stored config (global context)
var config = global.get('activeConfig') || {};
var ticker = ((config.rule_front && config.rule_front.data_source) || (config.rule_back && config.rule_back.data_source) || '').toString().trim().toUpperCase();

if (!ticker) {
    node.warn('No active config or ticker - click Activate Both Rules in the React app first');
    return [];
}

var token = global.get('finnhubToken') || 'd6jf171r01qomr5gj3r0d6jf171r01qomr5gj3rg';
msg.url = 'https://finnhub.io/api/v1/quote?symbol=' + ticker + '&token=' + token;
msg._config = config;
msg._ticker = ticker;
return msg;

// Map Finnhub response to haptic payload
var stock = msg.payload;
var config = msg._config || global.get('activeConfig') || {};
var ticker = msg._ticker || ((config.rule_front && config.rule_front.data_source) || (config.rule_back && config.rule_back.data_source) || '').toString().trim().toUpperCase();
var rule = config.rule_front || config.rule_back || {};

if (!stock || stock.d === null) return [];

const currentPrice = stock.c;
const percentChange = stock.dp || 0;
const dayHigh = stock.h || currentPrice;
const dayLow = stock.l || currentPrice;
const dayRange = dayHigh - dayLow;
const volatility = currentPrice ? (dayRange / currentPrice) * 100 : 0;
var baseIntensity = 40 + ((rule.intensity || 5) - 1) * (60 / 9);
var intensity = Math.min(100, Math.max(40, baseIntensity + Math.abs(percentChange) * 20));
const direction = percentChange >= 0 ? 'up' : 'down';

var pattern = (rule.pattern || 'pulse_all').toString();
if (pattern !== 'rising' && pattern !== 'falling') pattern = 'pulse_all';
msg.payload = {
    intensity: Math.round(intensity),
    direction: direction,
    pattern: pattern,
    price: currentPrice,
    change: percentChange,
    volatility: Math.round(volatility * 10) / 10
};
node.warn('💰 ' + ticker + ' $' + currentPrice + ' | ' + (direction === 'up' ? '📈' : '📉') + ' ' + percentChange + '% | ⚡ ' + msg.payload.intensity + '%');
return msg;
